function StatusTag({ status, styles }) {
  const s = styles[status] || styles[Object.keys(styles)[0]];
  return (
    <span className={`inline-flex items-center gap-1.5 font-mono text-xs tracking-wider ${s.text}`}>
      <span className={`h-1.5 w-1.5 rounded-full ${s.dot}`} />
      {s.label}
    </span>
  );
}

function renderDescription(description, t) {
  if (typeof description === "string") return description;
  return description.map((part, i) =>
    typeof part === "string" ? (
      <React.Fragment key={i}>{part}</React.Fragment>
    ) : (
      <span key={i} className={`${t.accent} font-medium`}>
        {part.hl}
      </span>
    )
  );
}

function SectionHeading({ eyebrow, title, subtitle, caption, icon: Icon, t }) {
  return (
    <div className="text-center max-w-2xl mx-auto mb-10 sm:mb-14">
      <p className={`inline-flex items-center gap-2 font-mono text-xs tracking-widest ${t.accent} mb-3`}>
        {Icon && <Icon size={13} />} {eyebrow}
      </p>
      <h2 className={`font-display text-3xl sm:text-4xl font-bold ${t.text} mb-2`}>{title}</h2>
      {subtitle && <p className={`font-body text-sm sm:text-base ${t.textMuted} mx-auto`}>{subtitle}</p>}
      {caption && <p className={`font-mono text-xs ${t.textFaint} mt-3`}>{caption}</p>}
    </div>
  );
}

/* ============================================================
   GitHub contribution activity (real data via a public,
   no-auth, CORS-enabled API that reads a user's public
   contribution graph: github-contributions-api.jogruber.de)
   ============================================================ */
const DOT_RADIUS_BY_LEVEL = [1.4, 2.2, 3, 3.8, 4.6];
// Level 0 = no contributions that day; levels 1-4 run light red -> dark red,
// same idea as GitHub's own green scale.
const DOT_COLOR_BY_LEVEL = ["#fecaca", "#fca5a5", "#f87171", "#dc2626", "#7f1d1d"];

function GithubActivity({ t, isDark }) {
  const [status, setStatus] = useState("loading"); // loading | ready | error
  const [weeks, setWeeks] = useState([]);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    let cancelled = false;
    fetch(`https://github-contributions-api.jogruber.de/v4/${PROFILE.githubUsername}?y=last`)
      .then((res) => {
        if (!res.ok) throw new Error("Request failed");
        return res.json();
      })
      .then((json) => {
        if (cancelled || !json || !Array.isArray(json.contributions)) throw new Error("Bad payload");
        const days = json.contributions;
        const sum = days.reduce((acc, d) => acc + (d.count || 0), 0);

        // Group into weeks (columns), Sunday-first rows, matching GitHub's own layout.
        const cols = [];
        let currentWeek = new Array(7).fill(null);
        days.forEach((day) => {
          const dow = new Date(day.date + "T00:00:00").getDay();
          currentWeek[dow] = day;
          if (dow === 6) {
            cols.push(currentWeek);
            currentWeek = new Array(7).fill(null);
          }
        });
        if (currentWeek.some((d) => d !== null)) cols.push(currentWeek);

        if (!cancelled) {
          setWeeks(cols);
          setTotal(sum);
          setStatus("ready");
        }
      })
      .catch(() => {
        if (!cancelled) setStatus("error");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const cellSize = 12;
  const width = weeks.length * cellSize;
  const height = 7 * cellSize;

  const term = isDark
    ? {
        panelBg: "bg-[#0a0f1a]",
        titleBarBg: "bg-[#0d1420]",
        border: "border-slate-800",
        prompt: "text-slate-500",
        output: "text-slate-300",
        muted: "text-slate-600",
        scanline: "text-red-400",
        emptySquare: "#1e293b",
      }
    : {
        panelBg: "bg-white",
        titleBarBg: "bg-slate-50",
        border: "border-slate-200",
        prompt: "text-slate-400",
        output: "text-slate-700",
        muted: "text-slate-400",
        scanline: "text-red-500",
        emptySquare: "#e2e8f0",
      };

  return (
    <section id="github-activity" className="max-w-6xl mx-auto px-5 sm:px-8 py-24">
      <Reveal>
        <div className="text-center mb-8 sm:mb-10">
          <p className={`inline-flex items-center gap-2 font-mono text-xs tracking-widest ${t.accent} mb-3`}>
            <Github size={13} /> 06 · GITHUB
          </p>
          <h2 className={`font-display text-3xl sm:text-4xl font-bold ${t.text}`}>Github Activity</h2>
          <p className={`font-mono text-xs ${t.textFaint} mt-3`}>
            Live contribution data pulled directly from GitHub.
          </p>
        </div>
      </Reveal>

      <Reveal>
        <div className={`rounded-xl overflow-hidden border ${term.border} shadow-2xl ${term.panelBg}`}>
          {/* Title bar */}
          <div className={`flex items-center gap-2 px-4 py-3 ${term.titleBarBg} border-b ${term.border}`}>
            <span className="h-3 w-3 rounded-full bg-red-500" />
            <span className="h-3 w-3 rounded-full bg-amber-400" />
            <span className="h-3 w-3 rounded-full bg-emerald-500" />
            <p className={`ml-3 font-mono text-[11px] ${term.prompt} truncate min-w-0 flex-1`}>
              arkey@ursystem:~$ ./github-activity.sh
            </p>
            <a
              href={PROFILE.github}
              target="_blank"
              rel="noreferrer"
              className={`ml-auto inline-flex items-center gap-1 font-mono text-[11px] ${term.prompt} hover:text-red-400 transition-colors shrink-0`}
            >
              @{PROFILE.githubUsername} <ExternalLink size={11} />
            </a>
          </div>

          {/* Terminal body */}
          <div className="relative px-5 py-6 sm:px-8 sm:py-8 font-mono text-[13px] leading-relaxed">
            <div className={`absolute inset-0 bg-scanlines ${term.scanline} pointer-events-none`} />
            <div className="relative">
              <p className={term.prompt}>
                <span className="text-red-400">$</span> curl -s api.github.com/users/{PROFILE.githubUsername}/contributions
              </p>

              {status === "loading" && (
                <p className={`${term.prompt} mt-2`}>
                  fetching contribution data<span className="animate-blink">_</span>
                </p>
              )}

              {status === "error" && (
                <p className={`${term.prompt} mt-2`}>
                  error: request failed — view directly on{" "}
                  <a href={PROFILE.github} target="_blank" rel="noreferrer" className="text-red-400 hover:underline">
                    github.com
                  </a>
                  <span className="animate-blink">_</span>
                </p>
              )}

              {status === "ready" && (
                <>
                  <p className={`${term.output} mt-2`}>
                    200 OK — <span className="text-red-400">{total.toLocaleString()}</span> contributions in the last year
                  </p>

                  <p className={`${term.prompt} mt-5 mb-3`}>
                    <span className="text-red-400">$</span> cat contributions.graph
                  </p>

                  <div className="overflow-x-auto -mx-1 px-1 pb-1">
                    <svg
                      viewBox={`0 0 ${width} ${height}`}
                      style={{ minWidth: `${width}px`, height: "auto" }}
                      className="block"
                    >
                      {weeks.map((week, wi) =>
                        week.map((day, di) => {
                          if (!day) return null;
                          const level = day.level ?? 0;
                          const fill = level === 0 ? term.emptySquare : DOT_COLOR_BY_LEVEL[level];
                          return (
                            <rect
                              key={`${wi}-${di}`}
                              x={wi * cellSize + 1.5}
                              y={di * cellSize + 1.5}
                              width={cellSize - 3}
                              height={cellSize - 3}
                              rx={2}
                              fill={fill}
                              opacity={level === 0 ? 0.5 : 1}
                            >
                              <title>{`${day.count} contributions on ${day.date}`}</title>
                            </rect>
                          );
                        })
                      )}
                    </svg>
                  </div>

                  <p className={`${term.muted} mt-4`}>
                    <span className="text-red-400">$</span> <span className="animate-blink">_</span>
                  </p>
                </>
              )}
            </div>
          </div>
        </div>
      </Reveal>
    </section>
  );
}

